/// <summary>
/// This is an extension class for TAMRebateDeal form TAMRebateTable data source.
/// </summary>
[ExtensionOf(formDataSourceStr(TAMRebateDeal, TAMRebateTable))]
internal final class METTAMRebateDeal_TAMRebateTable_Extension
{
}

Method.Source:
/// <summary>
/// Enable/Disable the form controls for the volumetric rebate deals.
/// </summary>
/// <returns>int</returns>
public int active()
{
    int ret = next active();

    // Bug 284448: CB705 - Vendor Claims external data source does not link the transaction to METExternalSellData table
    // moved inventDim logic here as it needs rebateTable record and after GUP extension
    FormDataSource inventDim_ds = this.formRun().dataSource(formDataSourceStr(TAMRebateDeal, InventDim));
    TAMRebateTable rebateTable = this.cursor();
    TAMRebateDeal rebateDeal = TAMRebateDeal::find(rebateTable.RebateDeal);

    boolean allowEditTierLineTypeValue = !rebateDeal.METVolumetricTierDeal
                                      || (rebateDeal.METVolumetricTierDeal && rebateTable.METTierLineType == METTierLineType::Value);

    inventDim_ds.allowEdit(inventDim_ds.allowEdit() && !rebateDeal.METUseExternalSellData && allowEditTierLineTypeValue);

    return ret;
}
